    /// v155 leaves the Flow Builder with the one harness Code Studio pins: the
    /// unused variants go together with their versions and executions, and the
    /// pinned row is renamed only while nobody has renamed it already.
    #[test]
    fn only_the_pinned_code_harness_survives_and_takes_its_plain_name() {
        let conn = Connection::open_in_memory().unwrap();
        run(&conn).unwrap();
        conn.execute_batch(
            "PRAGMA foreign_keys=ON;
             INSERT INTO flows (id, name, flow_json, status) VALUES
                ('cs-harness', 'Code Harness', '{}', 'active'),
                ('cs-harness-team', 'Code Harness — zespół QA', '{}', 'active'),
                ('cs-harness-critic', 'Code Harness — wymuszony potok z krytykiem', '{}', 'active');
             INSERT INTO flow_versions (id, flow_id, version_num, flow_json, name) VALUES
                ('cs-harness-factory', 'cs-harness', 1, '{}', 'Code Harness'),
                ('cs-harness-critic-factory', 'cs-harness-critic', 1, '{}', 'critic');
             INSERT INTO flow_executions (flow_id, status) VALUES
                ('cs-harness', 'success'), ('cs-harness-critic', 'success');",
        )
        .unwrap();

        keep_only_the_pinned_code_harness(&conn).unwrap();

        let flows: Vec<(String, String)> = conn
            .prepare("SELECT id, name FROM flows WHERE id LIKE 'cs-harness%' ORDER BY id")
            .unwrap()
            .query_map([], |r| Ok((r.get(0)?, r.get(1)?)))
            .unwrap()
            .collect::<rusqlite::Result<_>>()
            .unwrap();
        assert_eq!(
            flows,
            vec![("cs-harness-critic".to_string(), "Code Harness".to_string())]
        );
        let orphans: i64 = conn
            .query_row(
                "SELECT (SELECT COUNT(*) FROM flow_versions WHERE flow_id = 'cs-harness') \
                      + (SELECT COUNT(*) FROM flow_executions WHERE flow_id = 'cs-harness')",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(orphans, 0);
        let kept: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM flow_executions WHERE flow_id = 'cs-harness-critic'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(kept, 1, "the pinned harness keeps its history");
        assert!(foreign_key_check(&conn).unwrap().is_empty());

        conn.execute(
            "UPDATE flows SET name = 'Nasz harness' WHERE id = 'cs-harness-critic'",
            [],
        )
        .unwrap();
        keep_only_the_pinned_code_harness(&conn).unwrap();
        let name: String = conn
            .query_row(
                "SELECT name FROM flows WHERE id = 'cs-harness-critic'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(name, "Nasz harness", "an admin rename is not overwritten");
    }

    /// Capacity is registry data, usage is telemetry, and the split is the whole
    /// decision behind the host-capacity migration: the shape of a host changes when somebody
    /// opens the case and every node has to see it, while usage changes every
    /// second and rides the heartbeat (`PeerVirtInfo`, step 18). A usage column
    /// appearing here would mean a ledger row per sample.
    ///
    /// NULL, not zero, is what "not probed yet" reads as — a host with no probe
    /// must not render as a machine with no memory.
    #[test]
    fn vm_hosts_carries_hardware_capacity_and_not_usage() {
        let conn = Connection::open_in_memory().unwrap();
        run(&conn).unwrap();
        let mut stmt = conn.prepare("PRAGMA table_info(vm_hosts)").unwrap();
        let columns: Vec<(String, String, i64)> = stmt
            .query_map([], |r| {
                Ok((r.get::<_, String>(1)?, r.get::<_, String>(2)?, r.get::<_, i64>(3)?))
            })
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap();
        for capacity in ["cpu_cores", "ram_bytes", "storage_bytes"] {
            let column = columns
                .iter()
                .find(|(name, _, _)| name == capacity)
                .unwrap_or_else(|| panic!("vm_hosts must carry {capacity}"));
            assert_eq!(column.1, "INTEGER");
            assert_eq!(column.2, 0, "{capacity} must be nullable: NULL means unprobed");
        }
        for usage in ["cpu_used_pct", "ram_used_bytes", "storage_used_bytes"] {
            assert!(
                !columns.iter().any(|(name, _, _)| name == usage),
                "{usage} is telemetry and belongs in the heartbeat, not the ledger"
            );
        }
    }

    /// v156 is additive: it creates the account registry and gives every agent
    /// that already exists a runtime. The DEFAULT is what fills the rows an
    /// upgraded install already has — an agent with an empty `runtime_json`
    /// would fail to parse on the first read, so "no runtime" must be spelled
    /// out as the LLM one at the column level and not by a later repair.
    #[test]
    fn migration_v156_registers_provider_accounts_and_gives_every_agent_a_runtime() {
        let conn = Connection::open_in_memory().unwrap();
        run(&conn).unwrap();
        conn.execute_batch("PRAGMA foreign_keys = ON;").unwrap();

        for table in [
            "provider_accounts",
            "provider_account_grants",
            "provider_account_credentials",
            "provider_account_sessions",
            "provider_account_node_state",
            "agent_runtime_nodes",
            "agent_runtime_engines",
        ] {
            let found: i64 = conn
                .query_row(
                    "SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name=?1",
                    rusqlite::params![table],
                    |r| r.get(0),
                )
                .unwrap();
            assert_eq!(found, 1, "{table} is missing after the ladder");
        }

        // An agent written by code that predates the column reads as an LLM
        // agent, which is what every existing agent is.
        conn.execute(
            "INSERT INTO agents (id, name, description, tools_json, skills_json, params_json) \
             VALUES ('a1', 'old', 'd', '[]', '{}', '{}')",
            [],
        )
        .unwrap();
        let runtime: String = conn
            .query_row("SELECT runtime_json FROM agents WHERE id = 'a1'", [], |r| {
                r.get(0)
            })
            .unwrap();
        assert_eq!(runtime, r#"{"kind":"llm"}"#);

        // Two accounts of one org may not claim the same provider identity for
        // the same engine — that is one subscription, not two.
        conn.execute(
            "INSERT INTO provider_accounts \
               (account_id, org_id, engine_id, display_name, scope, credential_kind, \
                provider_subject, created_by) \
             VALUES ('acc1', 'org-default', 'codex', 'A', 'global', 'api_key', 'a@b.c', 'admin')",
            [],
        )
        .unwrap();
        assert!(
            conn.execute(
                "INSERT INTO provider_accounts \
                   (account_id, org_id, engine_id, display_name, scope, credential_kind, \
                    provider_subject, created_by) \
                 VALUES ('acc2', 'org-default', 'codex', 'B', 'global', 'api_key', 'a@b.c', 'admin')",
                [],
            )
            .is_err(),
            "the provider identity is unique per org and engine"
        );
        // A personal account without an owner, and a shared one with one, are
        // both nonsense the column CHECK refuses.
        for (scope, owner) in [("user", None), ("global", Some("u1"))] {
            assert!(
                conn.execute(
                    "INSERT INTO provider_accounts \
                       (account_id, org_id, engine_id, display_name, scope, credential_kind, \
                        owner_user_id, created_by) \
                     VALUES ('acc3', 'org-default', 'codex', 'C', ?1, 'api_key', ?2, 'admin')",
                    rusqlite::params![scope, owner],
                )
                .is_err(),
                "scope '{scope}' with owner {owner:?} must be refused"
            );
        }

        // Everything hanging off an account goes with it.
        conn.execute(
            "INSERT INTO provider_account_grants (account_id, subject_type, subject_id, granted_by) \
             VALUES ('acc1', 'org', '', 'admin')",
            [],
        )
        .unwrap();
        conn.execute(
            "DELETE FROM provider_accounts WHERE account_id = 'acc1'",
            [],
        )
        .unwrap();
        let orphans: i64 = conn
            .query_row("SELECT COUNT(*) FROM provider_account_grants", [], |r| {
                r.get(0)
            })
            .unwrap();
        assert_eq!(orphans, 0);
    }

    /// Strips what v156 adds, so the migration can be exercised on a database
    /// that really is at v155.
    fn rewind_to_v155(conn: &Connection) {
        conn.execute_batch(
            "DROP TABLE agent_runtime_engines; \
             DROP TABLE agent_runtime_nodes; \
             DROP TABLE provider_account_node_state; \
             DROP TABLE provider_account_sessions; \
             DROP TABLE provider_account_credentials; \
             DROP TABLE provider_account_grants; \
             DROP TABLE provider_accounts; \
             ALTER TABLE agents DROP COLUMN runtime_json;",
        )
        .unwrap();
        conn.execute("DELETE FROM _migrations WHERE version = 156", [])
            .unwrap();
    }

    /// The agents an installation already has must come out of the upgrade
    /// runnable. `runtime_json` is NOT NULL, so the only thing standing between
    /// an existing row and a failed `ALTER TABLE` is the column default — and
    /// the value it backfills has to be the runtime those agents actually have.
    #[test]
    fn migration_v156_upgrades_v155_database_without_data_loss() {
        let conn = Connection::open_in_memory().unwrap();
        run(&conn).unwrap();
        rewind_to_v155(&conn);
        assert!(
            !column_exists(&conn, "agents", "runtime_json").unwrap(),
            "the rewind must really land on v155"
        );

        for (id, name) in [("a1", "support"), ("a2", "researcher")] {
            conn.execute(
                "INSERT INTO agents (id, name, description, tools_json, skills_json, params_json) \
                 VALUES (?1, ?2, 'd', '[]', '{}', '{}')",
                rusqlite::params![id, name],
            )
            .unwrap();
        }
        let agents_before: i64 = conn
            .query_row("SELECT COUNT(*) FROM agents", [], |r| r.get(0))
            .unwrap();

        conn.execute_batch(PROVIDER_ACCOUNTS).unwrap();

        assert_eq!(
            conn.query_row("SELECT COUNT(*) FROM agents", [], |r| r.get::<_, i64>(0))
                .unwrap(),
            agents_before,
            "no agent may be lost by the upgrade"
        );
        let runtimes: Vec<(String, String)> = {
            let mut stmt = conn
                .prepare("SELECT id, runtime_json FROM agents ORDER BY id")
                .unwrap();
            let rows = stmt
                .query_map([], |r| Ok((r.get(0)?, r.get(1)?)))
                .unwrap()
                .collect::<std::result::Result<Vec<_>, _>>()
                .unwrap();
            rows
        };
        assert_eq!(
            runtimes,
            vec![
                ("a1".to_string(), r#"{"kind":"llm"}"#.to_string()),
                ("a2".to_string(), r#"{"kind":"llm"}"#.to_string()),
            ],
            "an agent that predates the column is an LLM agent, spelled out"
        );
        assert_eq!(
            conn.query_row("SELECT name FROM agents WHERE id = 'a1'", [], |r| r
                .get::<_, String>(0))
                .unwrap(),
            "support",
            "the upgrade rewrites no other column"
        );
        assert!(table_exists(&conn, "provider_accounts").unwrap());
    }

    /// Strips what v162 adds, so the migration runs on a database that really is
    /// at v161 — with a row of that vintage already inside it.
    fn rewind_to_v161(conn: &Connection) {
        conn.execute_batch(
            "DROP INDEX idx_model_metrics_account; \
             ALTER TABLE model_metrics_rollup DROP COLUMN account_id;",
        )
        .unwrap();
        conn.execute("DELETE FROM _migrations WHERE version = 162", [])
            .unwrap();
    }

    /// A rollup row written before the account dimension keeps its id, its
    /// numbers and its hour bucket: the column is added with a `''` default, so
    /// the only thing the upgrade changes is that the dimension exists. Re-keying
    /// or re-summing old rows here would move every historical total.
    #[test]
    fn migration_v162_upgrades_v161_database_without_data_loss() {
        let conn = Connection::open_in_memory().unwrap();
        run(&conn).unwrap();
        rewind_to_v161(&conn);
        assert!(
            !column_exists(&conn, "model_metrics_rollup", "account_id").unwrap(),
            "the rewind must really land on v161"
        );
        conn.execute(
            "INSERT INTO model_metrics_rollup \
               (id, node_id, org_id, user_id, model_id, service_key, backend, modality, \
                hour_bucket, histogram_version, request_count, total_tokens) \
             VALUES ('legacy-row', 'n1', 'org-default', 'u1', 'qwen', 'vllm:qwen', 'vllm', 'chat', \
                     '2026-08-19T10:00:00Z', 1, 3, 150)",
            [],
        )
        .unwrap();

        model_metrics_rollup_add_account_id(&conn).unwrap();

        let (id, account, tokens): (String, String, i64) = conn
            .query_row(
                "SELECT id, account_id, total_tokens FROM model_metrics_rollup",
                [],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .unwrap();
        assert_eq!(
            (id.as_str(), account.as_str(), tokens),
            ("legacy-row", "", 150)
        );
        // Running it again is a no-op, not a second ALTER.
        model_metrics_rollup_add_account_id(&conn).unwrap();
        let indexes: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM sqlite_master \
                 WHERE type = 'index' AND name = 'idx_model_metrics_account'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(indexes, 1);
    }

    /// v164 adds the marker that tells "this account's home was deleted" apart
    /// from "this account never had one". The upgrade is an ordinary `ADD COLUMN`
    /// and does NOT rewrite any row: a node upgrading into it cannot know which
    /// of its NULL homes were once real, and inventing an answer would print a
    /// deleted node's id on accounts that were never homed. The marker only ever
    /// describes a deletion this ladder witnessed.
    #[test]
    fn migration_v164_adds_the_lost_home_marker_without_rewriting_any_account() {
        let conn = Connection::open_in_memory().unwrap();
        run_ladder_up_to(&conn, 163);
        assert!(
            !column_exists(&conn, "provider_accounts", "home_lost_node_id").unwrap(),
            "the column must not exist before the rung runs"
        );
        for (account_id, home) in [("acc-homed", Some("node-a")), ("acc-never-homed", None)] {
            conn.execute(
                "INSERT INTO provider_accounts \
                   (account_id, org_id, engine_id, display_name, scope, credential_kind, \
                    home_node_id, status, created_by) \
                 VALUES (?1, 'default', 'codex', 'Shared codex', 'global', 'provider_login', \
                         ?2, 'active', 'admin')",
                rusqlite::params![account_id, home],
            )
            .unwrap();
        }

        apply_migration(
            &conn,
            164,
            "provider_account_home_lost",
            &MigrationStep::Sql(PROVIDER_ACCOUNT_HOME_LOST),
        )
        .unwrap();

        let rows: Vec<(String, Option<String>, Option<String>)> = conn
            .prepare(
                "SELECT account_id, home_node_id, home_lost_node_id FROM provider_accounts \
                 ORDER BY account_id",
            )
            .unwrap()
            .query_map([], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)))
            .unwrap()
            .collect::<Result<_, _>>()
            .unwrap();
        assert_eq!(
            rows,
            vec![
                ("acc-homed".to_string(), Some("node-a".to_string()), None),
                ("acc-never-homed".to_string(), None, None),
            ],
            "the home survives the upgrade and no row is marked as having lost one"
        );
    }

    /// v169 creates the map schema and v170 grants its permissions. The scene's
    /// foreign key must cascade — deleting a place deletes the reconstructions
    /// inside it, or the index would outlive the chunks on disk.
    #[test]
    fn migration_v169_creates_the_map_schema_and_v170_grants_its_permissions() {
        let conn = Connection::open_in_memory().unwrap();
        run_ladder_up_to(&conn, 168);
        assert!(
            !table_exists(&conn, "map_sites").unwrap(),
            "the map tables must not exist before the rung runs"
        );

        apply_migration(&conn, 169, "shared_maps", &MigrationStep::Sql(SHARED_MAPS)).unwrap();
        for table in [
            "map_sites",
            "map_scenes",
            "map_device_placements",
            "map_chunks",
            "map_device_sessions",
        ] {
            assert!(table_exists(&conn, table).unwrap(), "{table} was not created");
        }

        conn.execute_batch("PRAGMA foreign_keys = ON;").unwrap();
        conn.execute(
            "INSERT INTO map_sites (site_id, org_id, name, created_at_ms, updated_at_ms)              VALUES ('site-1', 'default', 'Hala', 1, 1)",
            [],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO map_scenes                (scene_id, site_id, org_id, name, owner_node_id, created_at_ms, updated_at_ms)              VALUES ('scn-1', 'site-1', 'default', 'Parter', 'helios', 1, 1)",
            [],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO map_device_placements                (scene_id, node_id, device_id, session_epoch, tx, ty, tz, qx, qy, qz, qw,                 method, set_at_ms, updated_at_ms)              VALUES ('scn-1', 'helios', 'go2-1', 1, 0, 0, 0, 0, 0, 0, 1, 'identity', 1, 1)",
            [],
        )
        .unwrap();
        conn.execute("DELETE FROM map_sites WHERE site_id = 'site-1'", [])
            .unwrap();
        let scenes: i64 = conn
            .query_row("SELECT COUNT(*) FROM map_scenes", [], |r| r.get(0))
            .unwrap();
        let placements: i64 = conn
            .query_row("SELECT COUNT(*) FROM map_device_placements", [], |r| r.get(0))
            .unwrap();
        assert_eq!(
            (scenes, placements),
            (0, 0),
            "deleting a site must take its scenes and their placements with it"
        );

        roles_add_map_permissions(&conn).unwrap();
        for (role, expected) in [
            ("org_admin", vec!["map.read", "map.write", "map.admin"]),
            ("org_operator", vec!["map.read", "map.write"]),
            ("org_viewer", vec!["map.read"]),
        ] {
            let json: String = conn
                .query_row(
                    "SELECT permissions_json FROM roles WHERE name = ?1",
                    rusqlite::params![role],
                    |r| r.get(0),
                )
                .unwrap();
            let perms: Vec<String> = serde_json::from_str(&json).unwrap();
            for want in &expected {
                assert!(perms.iter().any(|p| p == want), "{role} is missing {want}");
            }
            for absent in ["map.read", "map.write", "map.admin"]
                .iter()
                .filter(|p| !expected.contains(p))
            {
                assert!(
                    !perms.iter().any(|p| p == absent),
                    "{role} must not receive {absent}"
                );
            }
        }

        // Running it again grants nothing twice.
        roles_add_map_permissions(&conn).unwrap();
        let admin_json: String = conn
            .query_row(
                "SELECT permissions_json FROM roles WHERE name = 'org_admin'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        let perms: Vec<String> = serde_json::from_str(&admin_json).unwrap();
        assert_eq!(
            perms.iter().filter(|p| p.as_str() == "map.read").count(),
            1,
            "the grant must be idempotent"
        );
    }

    /// Seed one node-local coding-agent account the way the retired model wrote
    /// it: a `services` row whose configuration names the account, the deploy
    /// row that records which node put it there, a grant and an open session.
    fn seed_deployed_coding_agent_account(
        conn: &Connection,
        service: &str,
        account: &str,
        node: &str,
    ) {
        conn.execute(
            "INSERT INTO services \
               (engine_id, category, display_name, deploy_method, transport, config_json) \
             VALUES ('claude-code', 'agent', ?1, 'native_managed_cli', 'agent_rpc', ?2)",
            rusqlite::params![
                format!("Claude {service}"),
                format!(r#"{{"account_id":"{account}","model":"sonnet"}}"#)
            ],
        )
        .unwrap();
        let service_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO deployments (deploy_id, engine_id, deploy_method, node_id, status) \
             VALUES (?1, 'claude-code', 'native_managed_cli', ?2, 'running')",
            rusqlite::params![format!("deploy-{service}"), node],
        )
        .unwrap();
        conn.execute(
            "UPDATE services SET active_deploy_id = ?2 WHERE id = ?1",
            rusqlite::params![service_id, format!("deploy-{service}")],
        )
        .unwrap();
    }

    /// v160 adopts the accounts a node already runs into the replicated
    /// registry, together with the access decisions and session bindings that
    /// were written against their node-local service rows. The account id is
    /// kept verbatim because it is the name of the directory the account's
    /// logins already live in.
    ///
    /// The database is built UP TO v159 and the fixture is inserted there, so
    /// `run` below applies v160 for the first time from a recorded head that is
    /// below it — the state a node upgrading from before this rung is really
    /// in. Deleting v160's record from an already-migrated database does not
    /// reach that state: `run` skips every version at or below the recorded
    /// head, so the rung would be skipped and the assertions below would be
    /// reading rows the fixture never produced.
    #[test]
    fn migration_v160_adopts_deployed_coding_agents_into_the_registry() {
        let conn = Connection::open_in_memory().unwrap();
        run_ladder_up_to(&conn, 159);
        conn.execute_batch("PRAGMA foreign_keys = ON;").unwrap();

        conn.execute(
            "INSERT INTO user_accounts (id, username, password_hash, role, is_active) \
             VALUES ('admin-1', 'root', 'x', 'org_admin', 1)",
            [],
        )
        .unwrap();
        seed_deployed_coding_agent_account(&conn, "one", "acct-one", "node-a");
        // A service with no account of its own, and a coding agent that predates
        // the account model, are both left alone: neither names an identity.
        conn.execute(
            "INSERT INTO services \
               (engine_id, category, display_name, deploy_method, transport, config_json) \
             VALUES ('ollama', 'llm', 'Ollama', 'docker', 'http_direct', '{}')",
            [],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO services \
               (engine_id, category, display_name, deploy_method, transport, config_json) \
             VALUES ('codex', 'agent', 'Codex legacy', 'native_managed_cli', 'agent_rpc', '{}')",
            [],
        )
        .unwrap();

        let service_id: i64 = conn
            .query_row(
                "SELECT id FROM services WHERE display_name = 'Claude one'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        conn.execute(
            "INSERT INTO coding_agent_account_grants (service_id, user_id, granted_by) \
             VALUES (?1, 'admin-1', 'admin-1')",
            rusqlite::params![service_id],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO coding_agent_session_owners \
               (service_id, session_id, vendor_session_id, user_id) \
             VALUES (?1, 'sess-1', 'vendor-9', 'admin-1')",
            rusqlite::params![service_id],
        )
        .unwrap();

        // The rung runs where it really runs — through the ladder — rather than
        // by calling the SQL the test happens to have in hand. The ladder stops
        // before v165, which retires the grant table this rung reads; the end
        // of the test takes it to the head.
        for (rung, name, step) in get_migrations() {
            if (160..=164).contains(&rung) {
                apply_migration(&conn, rung, name, &step).unwrap();
            }
        }
        assert_eq!(
            conn.query_row(
                "SELECT name FROM _migrations WHERE version = 160",
                [],
                |r| r.get::<_, String>(0)
            )
            .unwrap(),
            "adopt_coding_agent_accounts",
            "the ladder must have applied v160, not skipped it"
        );

        let account: (String, String, String, String, String, Option<String>) = conn
            .query_row(
                "SELECT account_id, engine_id, scope, credential_kind, status, home_node_id \
                 FROM provider_accounts",
                [],
                |r| {
                    Ok((
                        r.get(0)?,
                        r.get(1)?,
                        r.get(2)?,
                        r.get(3)?,
                        r.get(4)?,
                        r.get(5)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(account.0, "acct-one", "the account id is the directory name");
        assert_eq!(account.1, "claude-code");
        assert_eq!(account.2, "global");
        assert_eq!(account.3, "provider_login");
        assert_eq!(
            account.4, "needs_login",
            "the node-local credential is not the identity the registry knows, so the account asks for a new sign-in"
        );
        assert_eq!(account.5.as_deref(), Some("node-a"));
        assert_eq!(
            conn.query_row(
                "SELECT display_name || '/' || org_id || '/' || created_by FROM provider_accounts",
                [],
                |r| r.get::<_, String>(0)
            )
            .unwrap(),
            "Claude one/org-default/admin-1"
        );

        let grant: (String, String, String) = conn
            .query_row(
                "SELECT subject_type, subject_id, granted_by FROM provider_account_grants",
                [],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .unwrap();
        assert_eq!(
            grant,
            (
                "user".to_string(),
                "admin-1".to_string(),
                "admin-1".to_string()
            )
        );

        let session: (String, String, Option<String>, Option<String>, String, Option<String>) = conn
            .query_row(
                "SELECT session_id, user_id, agent_id, workspace_id, node_id, vendor_session_id \
                 FROM provider_account_sessions",
                [],
                |r| {
                    Ok((
                        r.get(0)?,
                        r.get(1)?,
                        r.get(2)?,
                        r.get(3)?,
                        r.get(4)?,
                        r.get(5)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(session.0, "sess-1");
        assert_eq!(session.1, "admin-1");
        assert_eq!(session.2, None);
        assert_eq!(session.3, None);
        assert_eq!(session.4, "node-a");
        assert_eq!(session.5.as_deref(), Some("vendor-9"));

        // Nothing the running code still reads may move: the old tables keep
        // their rows and the service keeps the account id its directory is
        // derived from.
        assert_eq!(
            conn.query_row(
                "SELECT COUNT(*) FROM coding_agent_account_grants",
                [],
                |r| r.get::<_, i64>(0)
            )
            .unwrap(),
            1
        );
        assert_eq!(
            conn.query_row(
                "SELECT COUNT(*) FROM coding_agent_session_owners",
                [],
                |r| r.get::<_, i64>(0)
            )
            .unwrap(),
            1
        );
        assert_eq!(
            conn.query_row(
                "SELECT json_extract(config_json, '$.account_id') FROM services WHERE id = ?1",
                rusqlite::params![service_id],
                |r| r.get::<_, String>(0)
            )
            .unwrap(),
            "acct-one"
        );

        // Handed the same database again, the rung adds nothing: an upgrade that
        // is replayed — a restored backup, a retried open — must not double the
        // registry or overwrite an account someone has since edited.
        conn.execute(
            "UPDATE provider_accounts SET status = 'active', display_name = 'renamed'",
            [],
        )
        .unwrap();
        // Replayed through the rung the ladder carries, which is the only route
        // left once `_migrations` records a head above it: `run` skips every
        // version at or below that head, so deleting v160's row would replay
        // nothing and these assertions would hold vacuously.
        replay_migration(&conn, 160);
        assert_eq!(
            conn.query_row("SELECT COUNT(*) FROM provider_accounts", [], |r| r
                .get::<_, i64>(0))
                .unwrap(),
            1
        );
        assert_eq!(
            conn.query_row("SELECT COUNT(*) FROM provider_account_grants", [], |r| r
                .get::<_, i64>(0))
                .unwrap(),
            1
        );
        assert_eq!(
            conn.query_row("SELECT COUNT(*) FROM provider_account_sessions", [], |r| r
                .get::<_, i64>(0))
                .unwrap(),
            1
        );
        assert_eq!(
            conn.query_row(
                "SELECT status || '/' || display_name FROM provider_accounts",
                [],
                |r| r.get::<_, String>(0)
            )
            .unwrap(),
            "active/renamed",
            "a replayed rung leaves an adopted account exactly as it found it"
        );

        // v165 retires the per-service grant table; the grant it held lives on
        // in the registry, which is the only thing asked from now on.
        run(&conn).unwrap();
        assert!(!table_exists(&conn, "coding_agent_account_grants").unwrap());
        assert_eq!(
            conn.query_row("SELECT COUNT(*) FROM provider_account_grants", [], |r| r
                .get::<_, i64>(0))
                .unwrap(),
            1
        );
    }

    /// v166 removes the entire old "agent account = services row" path: the
    /// service row an agent deployed as, and the node-local session table that
    /// bound a session to it. The fixture also carries a `model_registry` row
    /// and an unrelated `ollama` service, so the test proves the cascade
    /// clears exactly the legacy row's children and leaves everything else.
    #[test]
    fn migration_v166_drops_the_legacy_agent_service_path() {
        let conn = Connection::open_in_memory().unwrap();
        run_ladder_up_to(&conn, 165);
        conn.execute_batch("PRAGMA foreign_keys = ON;").unwrap();

        conn.execute(
            "INSERT INTO user_accounts (id, username, password_hash, role, is_active) \
             VALUES ('admin-1', 'root', 'x', 'org_admin', 1)",
            [],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO services \
               (engine_id, category, display_name, deploy_method, transport, config_json) \
             VALUES ('codex', 'agent', 'Codex legacy', 'native_managed_cli', 'agent_rpc', '{}')",
            [],
        )
        .unwrap();
        let legacy_service_id = conn.last_insert_rowid();
        conn.execute(
            "INSERT INTO model_registry (service_id, model_name) VALUES (?1, 'codex-default')",
            rusqlite::params![legacy_service_id],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO coding_agent_session_owners (service_id, session_id, user_id) \
             VALUES (?1, 'sess-1', 'admin-1')",
            rusqlite::params![legacy_service_id],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO services \
               (engine_id, category, display_name, deploy_method, transport, config_json) \
             VALUES ('ollama', 'llm', 'Ollama', 'docker', 'http_direct', '{}')",
            [],
        )
        .unwrap();

        run(&conn).unwrap();

        assert!(
            !table_exists(&conn, "coding_agent_session_owners").unwrap(),
            "the node-local session table must be gone"
        );
        assert!(
            !index_exists(&conn, "coding_agent_sessions_user"),
            "its index must be gone with it"
        );
        assert_eq!(
            conn.query_row(
                "SELECT COUNT(*) FROM services WHERE deploy_method = 'native_managed_cli'",
                [],
                |r| r.get::<_, i64>(0)
            )
            .unwrap(),
            0,
            "every legacy agent-deployed-as-a-service row must be gone"
        );
        assert_eq!(
            conn.query_row(
                "SELECT COUNT(*) FROM model_registry WHERE service_id = ?1",
                rusqlite::params![legacy_service_id],
                |r| r.get::<_, i64>(0)
            )
            .unwrap(),
            0,
            "model_registry cascades on service_id"
        );
        assert_eq!(
            conn.query_row("SELECT COUNT(*) FROM services WHERE engine_id = 'ollama'", [], |r| r
                .get::<_, i64>(0))
                .unwrap(),
            1,
            "a service that never was a coding agent must survive"
        );
    }

    /// The adoption writes `org-default` as a literal, because a ladder rung is
    /// SQL and cannot read a Rust constant. Drift between the two would put
    /// adopted accounts in an organization nothing else looks at.
    #[test]
    fn the_adoption_migration_names_the_default_organization() {
        assert_eq!(
            crate::services::org::DEFAULT_ORG_ID,
            "org-default",
            "ADOPT_CODING_AGENT_ACCOUNTS hard-codes this org id in its SELECT"
        );
    }

    /// `sync_nodes.operator` is the organization's authority list, so it is a
    /// two-valued column with a safe default: a row that arrives from an older
    /// peer, or a migration of an existing install, must read as "not an
    /// operator" rather than as anything a caller happened to put there.
    #[test]
    fn sync_nodes_operator_is_two_valued_and_defaults_to_off() {
        let conn = Connection::open_in_memory().unwrap();
        run(&conn).unwrap();

        conn.execute(
            "INSERT INTO sync_nodes (node_id, public_key) VALUES ('n1', 'pk')",
            [],
        )
        .unwrap();
        let operator: i64 = conn
            .query_row(
                "SELECT operator FROM sync_nodes WHERE node_id = 'n1'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(operator, 0, "a node is not an operator until someone says so");

        assert!(
            conn.execute(
                "INSERT INTO sync_nodes (node_id, public_key, operator) VALUES ('n2', 'pk', 2)",
                [],
            )
            .is_err(),
            "the operator flag has exactly two values"
        );
        assert!(index_exists(&conn, "idx_sync_nodes_operator"));
    }

    /// plan-app-platform §5.1/W3: the ladder must apply every version exactly
    /// once, in order, with no gap and no duplicate — `get_migrations()` is
    /// the single source of truth `run()` iterates, so this is a property of
    /// the list itself, not of any one database.
    #[test]
    fn migration_ladder_is_contiguous_and_applies_each_version_once() {
        let versions: Vec<i64> = get_migrations().into_iter().map(|(v, _, _)| v).collect();
        let mut sorted = versions.clone();
        sorted.sort_unstable();
        assert_eq!(
            versions, sorted,
            "get_migrations() must be listed in version order"
        );
        for pair in sorted.windows(2) {
            assert_eq!(
                pair[1],
                pair[0] + 1,
                "migration ladder has a gap or duplicate between {} and {}",
                pair[0],
                pair[1]
            );
        }
        assert_eq!(*sorted.first().unwrap(), 1);
        // A literal here would be a second place the head is written down, and
        // the first one to go stale when a rung is added — the ladder itself is
        // the source, and `migration_ladder_head` reads the same list.
        assert_eq!(*sorted.last().unwrap(), migration_ladder_head());
        // plan-app-platform §7 W4 deleted the two bridge steps —
        // `bus_rbac_permissions_until_instance_matrix` (v145) and
        // `bus_groups_until_instance_db` (v146) — together with the
        // authorizer rewrite and the instance-db handle that made them dead.
        // Their NUMBERS stay occupied by `retired_migration` so the rungs
        // above them keep the versions databases already recorded.

        let conn = Connection::open_in_memory().unwrap();
        run(&conn).unwrap();
        let applied_count: i64 = conn
            .query_row("SELECT COUNT(*) FROM _migrations", [], |r| r.get(0))
            .unwrap();
        assert_eq!(
            applied_count,
            sorted.len() as i64,
            "each version must be recorded in _migrations exactly once"
        );
    }

    #[test]
    fn bus_schema_registry_tables_exist_after_migration() {
        let conn = Connection::open_in_memory().unwrap();
        run(&conn).unwrap();
        // FK enforcement (and the ON DELETE CASCADE below) is per-connection
        // and off by default in SQLite; production connections enable it in
        // `db/mod.rs::init`, this raw test connection must do the same.
        conn.execute_batch("PRAGMA foreign_keys = ON;").unwrap();

        conn.execute(
            "INSERT INTO bus_schema_subjects \
             (instance_id, org_id, subject, schema_type, compatibility, created_by, created_at_ms, updated_at_ms) \
             VALUES ('tentabus-00000001', 'org-1', 'orders.v1', 'json_schema', 'backward', 'admin-1', 0, 0)",
            [],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO bus_schema_versions \
             (instance_id, org_id, subject, version, schema_text, content_hash, schema_ref_id, created_by, created_at_ms) \
             VALUES ('tentabus-00000001', 'org-1', 'orders.v1', 1, '{}', 'hash-a', 1, 'admin-1', 0)",
            [],
        )
        .unwrap();

        let content_hash: String = conn
            .query_row(
                "SELECT content_hash FROM bus_schema_versions \
                 WHERE instance_id='tentabus-00000001' AND org_id='org-1' AND subject='orders.v1' AND version=1",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(content_hash, "hash-a");

        // Duplicate content_hash within the same instance's subject is rejected.
        let dup_hash = conn.execute(
            "INSERT INTO bus_schema_versions \
             (instance_id, org_id, subject, version, schema_text, content_hash, schema_ref_id, created_by, created_at_ms) \
             VALUES ('tentabus-00000001', 'org-1', 'orders.v1', 2, '{}', 'hash-a', 2, 'admin-1', 0)",
            [],
        );
        assert!(dup_hash.is_err(), "duplicate content_hash must be rejected");

        // Duplicate schema_ref_id within the same instance's org is
        // rejected, even across subjects.
        conn.execute(
            "INSERT INTO bus_schema_subjects \
             (instance_id, org_id, subject, schema_type, compatibility, created_by, created_at_ms, updated_at_ms) \
             VALUES ('tentabus-00000001', 'org-1', 'orders.v2', 'json_schema', 'backward', 'admin-1', 0, 0)",
            [],
        )
        .unwrap();
        let dup_ref = conn.execute(
            "INSERT INTO bus_schema_versions \
             (instance_id, org_id, subject, version, schema_text, content_hash, schema_ref_id, created_by, created_at_ms) \
             VALUES ('tentabus-00000001', 'org-1', 'orders.v2', 1, '{}', 'hash-b', 1, 'admin-1', 0)",
            [],
        );
        assert!(dup_ref.is_err(), "duplicate schema_ref_id must be rejected");

        // The SAME schema_ref_id is perfectly fine in a DIFFERENT instance
        // (plan-app-platform §1.4/W3 R5: schema_ref_id disambiguates within
        // one instance's org, not across instances).
        conn.execute(
            "INSERT INTO bus_schema_subjects \
             (instance_id, org_id, subject, schema_type, compatibility, created_by, created_at_ms, updated_at_ms) \
             VALUES ('tentabus-00000002', 'org-1', 'orders.v1', 'json_schema', 'backward', 'admin-1', 0, 0)",
            [],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO bus_schema_versions \
             (instance_id, org_id, subject, version, schema_text, content_hash, schema_ref_id, created_by, created_at_ms) \
             VALUES ('tentabus-00000002', 'org-1', 'orders.v1', 1, '{}', 'hash-a', 1, 'admin-1', 0)",
            [],
        )
        .expect("same schema_ref_id in a different instance must not collide");

        assert!(foreign_key_check(&conn).unwrap().is_empty());

        // Deleting a subject cascades its versions and leaves clean FKs.
        conn.execute(
            "DELETE FROM bus_schema_subjects WHERE instance_id='tentabus-00000001' AND org_id='org-1' AND subject='orders.v1'",
            [],
        )
        .unwrap();
        let remaining_versions: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM bus_schema_versions \
                 WHERE instance_id='tentabus-00000001' AND org_id='org-1' AND subject='orders.v1'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            remaining_versions, 0,
            "deleting a subject must cascade its versions"
        );
        assert!(foreign_key_check(&conn).unwrap().is_empty());
    }

    /// Review finding #1: a `bus_topics` row that predates v144 (registered
    /// via the wire-settable `validation`/free-text `schema_id` combination
    /// that has existed since M1) must never survive the upgrade with
    /// `validation != 'off'` — `bus_schema_subjects` is created in the very
    /// same migration transaction, so no such row's `schema_id` could
    /// possibly resolve yet.
    #[test]
    fn bus_schema_registry_migration_normalizes_pre_existing_non_off_validation() {
        let conn = Connection::open_in_memory().unwrap();
        run(&conn).unwrap();

        // `run()` already leaves a fresh database at v144, so there is no
        // way to observe a genuinely pre-migration row through the public
        // entry point — seed one directly, as if it had survived from a
        // pre-v144 install, then drive the data-fix helper the migration
        // itself calls.
        conn.execute(
            "INSERT INTO bus_topics (\
                instance_id, org_id, name, partitions, retention_ms, retention_bytes, cleanup_policy, \
                delivery, idempotency_key, dedup_window_ms, max_delivery_attempts, \
                retry_backoff_ms, schema_id, validation, content_type, replication_factor, \
                acks, durability, max_inline_bytes, compression, environment, \
                created_at_ms, updated_at_ms \
             ) VALUES (\
                'tentabus-00000001', 'org-1', 'orders.legacy', 8, 604800000, 10737418240, 'delete', \
                'at_least_once', NULL, 86400000, 5, 1000, 'hl7-adt-a01', 'warn', \
                'application/octet-stream', 1, 'leader', 'fsync_batch_full', 1048576, \
                'lz4', 'prod', 1000, 1000 \
             )",
            [],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO bus_topics (\
                instance_id, org_id, name, partitions, retention_ms, retention_bytes, cleanup_policy, \
                delivery, idempotency_key, dedup_window_ms, max_delivery_attempts, \
                retry_backoff_ms, schema_id, validation, content_type, replication_factor, \
                acks, durability, max_inline_bytes, compression, environment, \
                created_at_ms, updated_at_ms \
             ) VALUES (\
                'tentabus-00000001', 'org-1', 'orders.already-off', 8, 604800000, 10737418240, 'delete', \
                'at_least_once', NULL, 86400000, 5, 1000, NULL, 'off', \
                'application/octet-stream', 1, 'leader', 'fsync_batch_full', 1048576, \
                'lz4', 'prod', 1000, 1000 \
             )",
            [],
        )
        .unwrap();

        let reset = normalize_legacy_bus_topics_validation(&conn).unwrap();
        assert_eq!(reset, 1, "only the non-off row must be touched");

        let validation_of = |name: &str| -> String {
            conn.query_row(
                "SELECT validation FROM bus_topics WHERE name = ?1",
                rusqlite::params![name],
                |r| r.get(0),
            )
            .unwrap()
        };
        assert_eq!(validation_of("orders.legacy"), "off");
        assert_eq!(validation_of("orders.already-off"), "off");

        // Idempotent: re-running finds nothing left to touch.
        let reset_again = normalize_legacy_bus_topics_validation(&conn).unwrap();
        assert_eq!(reset_again, 0);
    }

    /// v173: a placement whose topic row is gone (deleted before v172, when
    /// a ledger delete left placements behind) is removed; the placements of
    /// a topic that exists — in this instance and org — are not, and neither
    /// is a same-named topic's placement in another instance.
    #[test]
    fn migration_173_removes_only_placements_without_a_topic() {
        let conn = Connection::open_in_memory().unwrap();
        run(&conn).unwrap();
        conn.execute(
            "INSERT INTO bus_topics (\
                instance_id, org_id, name, partitions, retention_ms, retention_bytes, cleanup_policy, \
                delivery, idempotency_key, dedup_window_ms, max_delivery_attempts, \
                retry_backoff_ms, schema_id, validation, content_type, replication_factor, \
                acks, durability, max_inline_bytes, compression, environment, \
                created_at_ms, updated_at_ms \
             ) VALUES (\
                'tentabus-00000001', 'org-1', 'orders.live', 1, 604800000, 10737418240, 'delete', \
                'at_least_once', NULL, 86400000, 5, 1000, NULL, 'off', \
                'application/octet-stream', 3, 'quorum', 'fsync_batch_full', 1048576, \
                'lz4', 'prod', 1000, 1000 \
             )",
            [],
        )
        .unwrap();
        for (instance, topic) in [
            ("tentabus-00000001", "orders.live"),
            ("tentabus-00000001", "orders.deleted"),
            ("tentabus-00000002", "orders.live"),
        ] {
            conn.execute(
                "INSERT INTO bus_partition_assignments \
                 (instance_id, org_id, topic, partition, leader_node_id, replicas, isr, \
                  leader_epoch, environment, updated_at_ms) \
                 VALUES (?1, 'org-1', ?2, 0, 'node-a', '[\"node-a\"]', '[\"node-a\"]', 3, \
                  'prod', 0)",
                rusqlite::params![instance, topic],
            )
            .unwrap();
        }

        bus_delete_orphan_assignments(&conn).unwrap();

        let mut left: Vec<(String, String)> = conn
            .prepare("SELECT instance_id, topic FROM bus_partition_assignments ORDER BY 1, 2")
            .unwrap()
            .query_map([], |r| Ok((r.get(0)?, r.get(1)?)))
            .unwrap()
            .collect::<rusqlite::Result<_>>()
            .unwrap();
        left.sort();
        assert_eq!(
            left,
            vec![("tentabus-00000001".to_string(), "orders.live".to_string())]
        );
    }

